impl ValueChecker for Range<OrderedFloat<FloatPayloadType>> {
    fn check_match(&self, payload: &Value) -> bool {
        match payload {
            Value::Number(num) => num
                .as_f64()
                .map(|number| self.check_range(OrderedFloat(number)))
                .unwrap_or(false),
            _ => false,
        }
    }
}
